async function handleCheckout(c: EngineCheckout): Promise<boolean> {
  const productKey = c.tier === 147 ? "au_147_cgt_discount_timing_sniper" : "au_67_cgt_discount_timing_sniper";
  const origin = window.location.origin;
  const successPath = c.tier === 147 ? "plan" : "assess";
  try {
    const res = await fetch("/api/create-checkout-session", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        decision_session_id: c.sessionId || `fallback_${c.tier}`,
        tier: c.tier,
        product_key: productKey,
        success_url: `${origin}/au/check/cgt-discount-timing-sniper/success/${successPath}`,
        cancel_url: `${origin}/au/check/cgt-discount-timing-sniper`,
      }),
    });
    if (!res.ok) return false;
    const data = await res.json();
    if (data.url) { window.location.href = data.url; return true; }
    return false;
  } catch {
    return false;
  }
}

export default function CgtDiscountTimingSniperCalculator() {
  return (
    <EngineCalculator
      engine={engine as Engine}
      figures={figures as EngineFigure[]}
      config={ENGINE_CONFIG}
      onCheckout={handleCheckout}
    />
  );
}
